<script setup>
import { onMounted, reactive, ref } from 'vue'
import { api, money, time, orderStates, codeStates, stateType } from '../../api'
import { usePage } from '../../composables/usePage'
import { ElMessage, ElMessageBox } from 'element-plus'
import LoadState from '../../components/LoadState.vue'
const filters = reactive({ keyword: '', status: '' }), { rows, total, page, loading, error, load, search } = usePage('/admin/orders', filters)
const dialog = ref(false), detail = ref(null), detailLoading = ref(false), detailError = ref(''), selected = ref(''), closing = ref(null)
async function show(orderNo) { selected.value = orderNo; detail.value = null; detailError.value = ''; dialog.value = true; detailLoading.value = true; try { detail.value = await api.get(`/admin/orders/${orderNo}`) } catch (e) { detailError.value = e.message } finally { detailLoading.value = false } }
async function close(row) { try { await ElMessageBox.confirm(`确定关闭订单 ${row.orderNo}？仅待支付订单可关闭，此操作会记录审计日志。`, '关闭订单', { confirmButtonText: '确认关闭', cancelButtonText: '取消', type: 'warning' }); closing.value = row.orderNo; const order = await api.post(`/admin/orders/${row.orderNo}/close`); if (detail.value?.orderNo === row.orderNo) detail.value = order; ElMessage.success('订单已关闭'); await load() } catch (e) { if (e instanceof Error) ElMessage.error(e.message) } finally { closing.value = null } }
onMounted(load)
</script>
<template><div class="page-heading"><div><div class="eyebrow">TRANSACTIONS & DELIVERY</div><h1>订单管理</h1><p>查询交易状态，核对订单快照与交付结果。</p></div></div><section class="surface admin-table-panel"><form class="table-toolbar" @submit.prevent="search"><el-input v-model="filters.keyword" placeholder="搜索订单号 / 商品名称" clearable aria-label="订单搜索" @clear="search" /><el-select v-model="filters.status" placeholder="全部状态" clearable aria-label="订单状态" @change="search"><el-option v-for="(label, state) in orderStates" :key="state" :label="label" :value="state" /></el-select><el-button native-type="submit">查询</el-button><span class="toolbar-count">共 {{ total }} 笔</span></form><LoadState :loading="loading" :error="error" :empty="!rows.length" empty-text="没有符合条件的订单" @retry="load"><el-table :data="rows"><el-table-column prop="orderNo" label="订单号" min-width="225"><template #default="{ row }"><el-button link type="primary" class="mono" @click="show(row.orderNo)">{{ row.orderNo }}</el-button></template></el-table-column><el-table-column prop="productName" label="商品快照" min-width="150" /><el-table-column prop="userId" label="买家 ID" width="90" /><el-table-column label="金额" width="100"><template #default="{ row }">¥ {{ money(row.amount) }}</template></el-table-column><el-table-column label="状态" width="105"><template #default="{ row }"><el-tag :type="stateType(row.status)">{{ orderStates[row.status] || row.status }}</el-tag></template></el-table-column><el-table-column label="创建时间" min-width="180"><template #default="{ row }">{{ time(row.createdAt) }}</template></el-table-column><el-table-column label="操作" width="135" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="show(row.orderNo)">详情</el-button><el-button v-if="row.status === 'WAIT_PAY'" link type="danger" :loading="closing === row.orderNo" @click="close(row)">关闭</el-button></template></el-table-column></el-table><el-pagination v-if="total > 15" v-model:current-page="page" :page-size="15" :total="total" layout="total, prev, pager, next" class="pagination" @current-change="load" /></LoadState></section><el-dialog v-model="dialog" title="订单详情" width="680px"><LoadState :loading="detailLoading" :error="detailError" @retry="show(selected)"><template v-if="detail"><div class="panel-title"><strong class="mono">{{ detail.orderNo }}</strong><el-tag :type="stateType(detail.status)">{{ orderStates[detail.status] || detail.status }}</el-tag></div><dl class="detail-list"><div><dt>商品快照</dt><dd>{{ detail.productName }}</dd></div><div><dt>订单金额</dt><dd>¥ {{ money(detail.amount) }}</dd></div><div><dt>买家 ID</dt><dd>{{ detail.userId }}</dd></div><div><dt>创建时间</dt><dd>{{ time(detail.createdAt) }}</dd></div><div><dt>支付时间</dt><dd>{{ time(detail.paidAt) }}</dd></div><div><dt>发货时间</dt><dd>{{ time(detail.deliveredAt) }}</dd></div></dl><div v-if="detail.redeemCode" class="info-note"><strong>已交付兑换码 · {{ codeStates[detail.redeemCode.status] }}</strong><p class="mono">{{ detail.redeemCode.code }}</p><p>有效期：{{ detail.redeemCode.expiredAt ? time(detail.redeemCode.expiredAt) : '长期有效' }}</p></div></template></LoadState><template #footer><el-button v-if="detail?.status === 'WAIT_PAY'" type="danger" :loading="closing === detail.orderNo" @click="close(detail)">关闭订单</el-button><el-button @click="dialog = false">返回</el-button></template></el-dialog></template>
